contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount1, uint256 amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(address(this).balance >= amount1 + amount2);

        // first deposit to set an initial balance
        c.Deposit{value: amount1}(); if (__ESBMC_reverted()) return;
        uint256 balMid = c.balances(address(this)); if (__ESBMC_reverted()) return;

        uint256 expected = balMid + amount2;
        bool overflow = expected < balMid;

        bool reverted;
        c.Deposit{value: amount2}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert((reverted && overflow && balAfter == balMid) || (!reverted && !overflow && balAfter == expected));
    }

    receive() external payable {}
}

