// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount1 + amount2);
        try c.Deposit{value: amount1}() {} catch { return; }
        uint256 balMid;
        try c.balances(address(this)) returns (uint256 __r) { balMid = __r; } catch { return; }
        uint256 expected = balMid + amount2;
        bool overflow = expected < balMid;
        bool reverted;
        try c.Deposit{value: amount2}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        assertTrue((reverted && overflow && balAfter == balMid) || (!reverted && !overflow && balAfter == expected));
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
